  readonly List<AudioWindow> audioWindows=new List<AudioWindow>();ShopAudio mixAudio;float audioLastRms;int[] audioClipIds;
  static string AudioHash(string path){using(var hash=SHA256.Create())return BitConverter.ToString(hash.ComputeHash(File.ReadAllBytes(path))).Replace("-","").ToLowerInvariant();}
  void AudioFlush(){File.WriteAllText(Path.Combine(evidence,"audio-mix.json"),JsonUtility.ToJson(new AudioMixReceipt{windows=audioWindows.ToArray()},true));}
  void AudioTopology(string label)
  {var sources=shop.GetComponents<AudioSource>();int loops=0;foreach(var s in sources){if(s.loop)loops++;Check(!s.playOnAwake&&!s.ignoreListenerVolume,"Owned voice respects master and explicit lifecycle / "+label);}Check(sources.Length==5&&loops==2&&mixAudio.MixSnapshot.VoiceCapacity==5&&mixAudio.ActiveVoiceCount<=5,"Exact three short plus two loop voices / "+label);var clips=mixAudio.MixValidationClips();if(audioClipIds==null){audioClipIds=new int[clips.Length];for(int i=0;i<clips.Length;i++)audioClipIds[i]=clips[i].Clip.GetInstanceID();}else{Check(clips.Length==audioClipIds.Length,"Stable generated clip count / "+label);for(int i=0;i<clips.Length;i++)Check(clips[i].Clip.GetInstanceID()==audioClipIds[i],"Stable generated clip identity / "+label+" / "+i);}}
  void AudioDryExport()
  {
   var clips=mixAudio.MixValidationClips();Check(clips.Length==25,"Exact25 original generated clips");var rows=new AudioPcmRow[clips.Length];int loops=0;
   for(int n=0;n<clips.Length;n++)
   {
    var info=clips[n];var c=info.Clip;var data=new float[c.samples*c.channels];Check(c.GetData(data,0),"Read exact generated PCM / "+c.name);double sum=0,squares=0;float peak=0,maxStep=0;
    for(int i=0;i<data.Length;i++){float v=data[i];if(float.IsNaN(v)||float.IsInfinity(v))throw new InvalidOperationException("Nonfinite clip "+c.name);sum+=v;squares+=(double)v*v;peak=Mathf.Max(peak,Mathf.Abs(v));if(i>0)maxStep=Mathf.Max(maxStep,Mathf.Abs(v-data[i-1]));}
    var row=new AudioPcmRow{index=n,name=c.name,file="audio-dry-"+n.ToString("00")+".wav",loop=info.Loop,samples=c.samples,channels=c.channels,frequency=c.frequency,peak=peak,rms=(float)Math.Sqrt(squares/data.Length),dc=(float)(sum/data.Length),first=data[0],last=data[data.Length-1],wrapJump=Mathf.Abs(data[0]-data[data.Length-1]),wrapSlopeJump=Mathf.Abs((data[1]-data[0])-(data[data.Length-1]-data[data.Length-2]))};
    Check(c.channels==1&&c.frequency==22050&&peak<1,"Actual dry format and unclipped PCM / "+c.name);
    if(info.Loop){loops++;Check(c.samples==88200&&peak<=.14001f&&row.rms<=.05001f&&Mathf.Abs(row.dc)<=.0001f&&row.wrapJump<=maxStep+.000001f,"Original loop PCM quiet DC and periodic join / "+c.name);}
    string path=Path.Combine(evidence,row.file);using(var w=new BinaryWriter(File.Create(path))){w.Write(System.Text.Encoding.ASCII.GetBytes("RIFF"));w.Write(36+data.Length*2);w.Write(System.Text.Encoding.ASCII.GetBytes("WAVEfmt "));w.Write(16);w.Write((short)1);w.Write((short)c.channels);w.Write(c.frequency);w.Write(c.frequency*c.channels*2);w.Write((short)(c.channels*2));w.Write((short)16);w.Write(System.Text.Encoding.ASCII.GetBytes("data"));w.Write(data.Length*2);foreach(float v in data)w.Write((short)Mathf.RoundToInt(v*32767));}row.sha256=AudioHash(path);rows[n]=row;
   }
   Check(loops==2,"Exactly two sustained loop clips");File.WriteAllText(Path.Combine(evidence,"audio-pcm.json"),JsonUtility.ToJson(new AudioPcmReceipt{clips=rows},true));
  }
  IEnumerator AudioMeasure(string label,float seconds,bool warm=true)
  {
   const int count=1024;int channels=AudioSettings.speakerMode==AudioSpeakerMode.Mono?1:2;var channel=new float[count];var all=new float[count*channels];
   for(int c=0;c<channels;c++)AudioListener.GetOutputData(channel,c);if(warm)yield return new WaitForSecondsRealtime(.15f);
   double totalSquare=0;long total=0;float start=Time.realtimeSinceStartup;
   try{while(Time.realtimeSinceStartup-start<seconds){double sum=0,square=0;float peak=0;for(int c=0;c<channels;c++){AudioListener.GetOutputData(channel,c);Array.Copy(channel,0,all,c*count,count);foreach(float v in channel){if(float.IsNaN(v)||float.IsInfinity(v))throw new InvalidOperationException("Nonfinite listener mix");sum+=v;square+=(double)v*v;peak=Mathf.Max(peak,Mathf.Abs(v));}}Check(peak<1,"Observed listener window unclipped / "+label);var s=mixAudio.MixSnapshot;string file="mix-window-"+audioWindows.Count.ToString("000")+".json";string path=Path.Combine(evidence,file);File.WriteAllText(path,JsonUtility.ToJson(new AudioRawWindow{data=(float[])all.Clone(),channels=channels,samplesPerChannel=count}));audioWindows.Add(new AudioWindow{label=label,file=file,sha256=AudioHash(path),renderFrame=Time.frameCount,realtime=Time.realtimeSinceStartup,dspTime=AudioSettings.dspTime,sampleRate=AudioSettings.outputSampleRate,channels=channels,samplesPerChannel=count,master=AudioListener.volume,ambience=shop.AmbienceVolume,humor=shop.HumorVolume,peak=peak,rms=(float)Math.Sqrt(square/all.Length),dc=(float)(sum/all.Length),waterGain=s.WaterGain,waterTarget=s.WaterTarget,machineGain=s.MachineGain,machineTarget=s.MachineTarget,duck=s.DuckGain,door=s.DoorFraction,working=s.MachineWorking,suspended=s.Suspended,inLab=s.PlayerInLab,waterSource=s.WaterSourceId,machineSource=s.MachineSourceId,listener=s.ListenerPosition,waterPosition=s.WaterSourcePosition,machinePosition=s.MachineSourcePosition,activeVoices=s.ActiveVoices});totalSquare+=square;total+=all.Length;yield return new WaitForSecondsRealtime(seconds<.5f?.025f:.125f);}}finally{AudioFlush();}
   audioLastRms=(float)Math.Sqrt(totalSquare/Math.Max(1,total));AudioTopology(label);
  }
